mapper.insert:
INSERT INTO pjt_approval_documents (
    doc_no, title, content, status, doc_class, current_step, version, drafter_id, file_group_id,
    scheduled_submit_at, submitted_at, completed_at, created_at, updated_at
) VALUES (
    #{docNo}, #{title}, #{content}, #{status}, #{docClass}, #{currentStep}, #{version}, #{drafterId}, #{fileGroupId},
    #{scheduledSubmitAt}, #{submittedAt}, #{completedAt}, #{createdAt}, #{updatedAt}
)

mapper.select:
SELECT * FROM pjt_approval_documents
WHERE status = 'SCHEDULED'
  AND scheduled_submit_at IS NOT NULL
  AND scheduled_submit_at <= #{now}
ORDER BY scheduled_submit_at ASC, id ASC
LIMIT #{limit}

choose.when:
AND id IN (
    SELECT document_id FROM pjt_approval_lines
    WHERE approver_id = #{viewerId}
      AND status = 'PENDING'
      AND line_type IN ('APPROVE', 'AGREE', 'POST')
      AND (
        (line_type IN ('APPROVE', 'AGREE') AND active = TRUE)
        OR line_type = 'POST'
      )
)

AND id IN (
    SELECT document_id FROM pjt_approval_lines
    WHERE approver_id = #{viewerId}
      AND status = 'HELD'
      AND line_type IN ('APPROVE', 'AGREE', 'POST')
)

AND id IN (
    SELECT document_id FROM pjt_approval_lines
    WHERE approver_id = #{viewerId}
      AND status = 'APPROVED'
      AND line_type IN ('APPROVE', 'AGREE', 'POST')
)

choose.otherwise:
AND (
    drafter_id = #{viewerId}
    OR id IN (SELECT document_id FROM pjt_approval_lines WHERE approver_id = #{viewerId})
)

mapper.select:
SELECT * FROM pjt_approval_documents

ORDER BY updated_at DESC, id DESC
LIMIT #{limit} OFFSET #{offset}
